// Fim dos Tempos · Arco 2 · O Labirinto Liberto · gerado por a2-labirinto-liberto.js
const DADOS = {"cadernos":[{"n":1,"verdade":true,"texto":"A caravana dos exilados de Lamnor foi guiada por Roramar Pruss, que teve visões proféticas ainda na infância."},{"n":2,"verdade":true,"texto":"A Rainha-Imperatriz Shivara ficou anos desaparecida durante a Guerra Artoniana."},{"n":3,"verdade":true,"texto":"A palavra escrita foi uma dádiva de Tanna-Toh."},{"n":4,"verdade":false,"texto":"A Marcha de Arsenal foi detida quando aventureiros se infiltraram em seu Kishinauros ainda em movimento e surpreenderam o vilão."},{"n":5,"verdade":false,"texto":"O reino de Salistick foi amaldiçoado pelos deuses quando seu primeiro regente se recusou a construir um templo ao Panteão."},{"n":6,"verdade":false,"texto":"Os puristas se revelaram depois que Shivara foi raptada pelos finntroll."},{"n":7,"verdade":false,"texto":"O Rio dos Deuses recebe este nome porque representava a fronteira quando o continente foi dividido entre Khalmyr e Nimb, numa disputa ancestral."},{"n":8,"verdade":false,"texto":"A primeira civilização humana de Arton foi o Império Manzirr, mais tarde desfeito em vários reinos durante a Grande Batalha."},{"n":9,"verdade":false,"texto":"Thwor Khoshkothruk nasceu durante uma noite que durou um dia inteiro."},{"n":10,"verdade":false,"texto":"A rivalidade entre Vectorius e Talude começou quando Vectorius foi expulso da Academia Arcana."},{"n":11,"verdade":true,"texto":"Dahllan são capazes de se comunicar com animais."},{"n":12,"verdade":true,"texto":"O Rei-Imperador Thormy foi aventureiro em sua juventude."},{"n":13,"verdade":true,"texto":"O Dragão da Tormenta só foi derrotado pela união de arquimagos e do próprio Dragão-Rei Sckhar."},{"n":14,"verdade":false,"texto":"Quando um deus maior cai ou morre, o restante do Panteão se reúne para decidir quem ocupará o lugar vago, já que sempre deve haver vinte."},{"n":15,"verdade":true,"texto":"A cidade-fortaleza de Khalifor foi batizada em homenagem a Khalil, que comandou uma expedição ao norte."},{"n":16,"verdade":false,"texto":"O caçador de recompensas Crânio Negro roubou a espada Rhumnam dos anões de Doherimm."},{"n":17,"verdade":false,"texto":"Sir Orion Drake descobriu que apenas o poder da fé artoniana era capaz de derrotar a Tormenta."},{"n":18,"verdade":true,"texto":"Os elfos chegaram a Arton vindos do Reino de Glórienn."},{"n":19,"verdade":false,"texto":"A cidade fora da lei de Smokestone fica em algum lugar de Namalkah."},{"n":20,"verdade":true,"texto":"No início de tudo, havia o Nada e o Vazio."},{"n":21,"verdade":false,"texto":"O arquimago Reynard foi o primeiro a travar contato com os Lordes da Tormenta."},{"n":22,"verdade":true,"texto":"Kallyadranoch exige que seus devotos paguem tributo em ouro ou sacrifícios."},{"n":23,"verdade":false,"texto":"Os hynne foram criados quando Hyninn roubou um pedaço da essência dos humanos (por isso são tão pequenos)."},{"n":24,"verdade":true,"texto":"Megalokk corrompeu as criações de Allihanna para dar origem aos primeiros monstros."},{"n":25,"verdade":false,"texto":"Quando a Tormenta recaiu sobre Arton pela primeira vez, a estátua de Valkaria chorou lágrimas de sangue."},{"n":26,"verdade":false,"texto":"A Caravana dos Exilados de Lamnor se perdeu durante anos após a traição do alto clérigo de Ghondriann."},{"n":27,"verdade":false,"texto":"Sszzaas tramou para assassinar Khalmyr através dos Rubis da Virtude."},{"n":28,"verdade":true,"texto":"Dragões nunca formaram sociedades ou civilizações."},{"n":29,"verdade":false,"texto":"As sereias são capazes de se comunicar com animais aquáticos."},{"n":30,"verdade":true,"texto":"As fadas foram criadas a partir de um sonho de Wynna, após ouvir os sussurros de Nimb."},{"n":31,"verdade":false,"texto":"Antes de ser Rainha-Imperatriz, Shivara foi monarca de Trebuck e Bielefeld."},{"n":32,"verdade":false,"texto":"Elfos e anões se enfrentaram na Guerra da Flecha e do Machado."},{"n":33,"verdade":false,"texto":"Os elfos foram criados por Glórienn como um aperfeiçoamento das fadas de Wynna."},{"n":34,"verdade":true,"texto":"A vida em Arton surgiu a partir de uma lágrima de Lena."},{"n":35,"verdade":true,"texto":"Os Rubis da Virtude foram criados como sugestão de Nimb, cada um contendo o poder de um dos deuses maiores do Panteão."}]};
(async function macroPrensa(D) {
		const tokens = canvas.tokens.controlled.filter((t) => t.actor);
		const res = await foundry.applications.api.DialogV2.prompt({
			window: { title: "Labirinto · A Prensa de Tanna-Toh" },
			position: { width: 620, height: 640 },
			content: `
				<p>Marque os <b>10 cadernos</b> que os jogadores escolheram para o livro <i>História e Fatos sobre Arton</i>. Sem testes e sem consultar o cenário: só a memória dos jogadores. Selecione os tokens do grupo.</p>
				<div class="form-group"><label>Ação</label><select name="acao"><option value="livro">Encadernar o livro</option><option value="sair">O grupo saiu do Labirinto (tira a punição dos selecionados)</option></select></div>
				<div style="max-height:380px;overflow-y:auto">${D.cadernos.map((c) => `<label style="display:block"><input type="checkbox" name="c_${c.n}"> <b>${c.n}.</b> ${c.texto}</label>`).join("")}</div>`,
			ok: { label: "Aplicar", callback: (ev, button) => Object.fromEntries(new FormData(button.form)) }
		});
		if (!res) return;
		const punicao = (a) => a.effects.find((e) => e.getFlag("world", "fdtPrensa"));
		if (res.acao === "sair") {
			for (const t of tokens) { const e = punicao(t.actor); if (e) await e.delete(); }
			return ui.notifications.info("Punição de Tanna-Toh removida dos selecionados.");
		}
		const escolhidos = D.cadernos.filter((c) => res[`c_${c.n}`]);
		if (escolhidos.length !== 10) return ui.notifications.warn(`O livro precisa de exatamente 10 cadernos (marcados: ${escolhidos.length}).`);
		const falsos = escolhidos.filter((c) => !c.verdade);
		if (!falsos.length) {
			return ChatMessage.create({ content: "<h3>A Prensa de Tanna-Toh</h3><p>A prensa encaderna o livro, e as duas portas de metal se destravam com um estalo: atrás de uma delas, a <b>Câmara do Helladarion</b>; a outra leva à Ligação.</p>" });
		}
		for (const t of tokens) {
			const e = punicao(t.actor);
			const n = (Number(e?.getFlag("world", "fdtPrensa")) || 0) + 1;
			const dados = {
				name: `Punição de Tanna-Toh (–${2 * n} em perícias)`,
				img: "systems/tormenta20/icons/itens/gerais/livro.webp",
				type: "base",
				description: "Montaram um livro com informações falsas. Vale enquanto estiverem no Labirinto Liberto; sair e voltar mais tarde remove a punição. Cumulativa.",
				flags: { world: { fdt: "a2labirinto", fdtPrensa: n } },
				system: { changes: [{ key: "system.pericias.*.bonus", value: String(-2 * n), type: "add", phase: "initial", priority: null }] }
			};
			if (e) await e.update(dados);
			else await t.actor.createEmbeddedDocuments("ActiveEffect", [dados]);
		}
		await ChatMessage.create({ content: `<h3>A Prensa de Tanna-Toh</h3><p>O livro sai da prensa, mas as portas continuam trancadas. A punição de Tanna-Toh recai sobre ${tokens.length ? tokens.map((t) => t.name).join(", ") : "o grupo (selecione os tokens para aplicar)"}: <b>–2 em todos os testes de perícia</b> (cumulativo) enquanto estiverem no Labirinto.</p>` });
		await ChatMessage.create({ content: `<p>Cadernos falsos no livro: ${falsos.map((c) => c.n).join(", ")}.</p>`, whisper: ChatMessage.getWhisperRecipients("GM") });
	})(DADOS);
